import{_ as t,o as l,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-11-07 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-11-07 -- Ceph Performance Meeting","date":"2019-11-07T00:00:00.000Z","updated":"2019-11-08T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","bluestore","bluefs","rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","损坏编码","复制","快照","克隆","瘦配置","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表板","管理","自动化","集成","容器化","Kubernetes","Docker","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑","失败域","恢复","弹性","负载均衡","缓存","压缩","去重","等级存储","性能调整","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-07_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-11-07_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780459816000}'),s={name:"posts/2019/2019-11-07_-_-_Ceph_Performance_Meeting.md"};function i(n,e,p,a,_,g){return l(),o("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>：</p><ul><li>Ceph 研发人员、字幕翻译及总结人员等</li></ul><p><strong>会议内容</strong>：</p><p><strong>一、Ceph 相关议题</strong></p><ol><li><p><strong>并行压缩问题</strong>：</p><ul><li>用户反馈 RocksDB 损坏可能与并行压缩参数更改有关。研发人员已创建不合并分支调查问题。</li></ul></li><li><p><strong>深度清理问题</strong>：</p><ul><li>用户报告即使关闭深度清理，仍有大量深度清理进行。建议增加深度清理的睡眠时间并逐步增加。</li></ul></li><li><p><strong>范围删除问题</strong>：</p><ul><li>用户反馈范围删除导致性能下降和内存碎片。建议在删除大量对象时禁用范围删除并进一步调查。</li></ul></li><li><p><strong>删除范围与RocksDB损坏问题</strong>：</p><ul><li>研发人员表示删除范围可能与RocksDB损坏问题有关。建议在Nautilus版本中禁用删除范围并回退到RocksDB旧版本。</li></ul></li><li><p><strong>PG数量问题</strong>：</p><ul><li>讨论了增加PG数量可能带来的问题，建议在减少PG数量时增加PG日志长度。</li></ul></li></ol><p><strong>二、后续行动计划</strong></p><ul><li>研发人员将继续调查并行压缩、深度清理、范围删除和RocksDB损坏问题。</li><li>用户将根据建议调整深度清理和范围删除的设置。</li><li>研发人员将考虑更改PG数量和PG日志长度的默认值。</li></ul><p><strong>三、其他事项</strong></p><ul><li>讨论了自动缩放器、数据移动和AWS环境等议题。</li></ul><p><strong>四、总结</strong></p><p>本次会议讨论了Ceph中的一些重要问题，并制定了后续行动计划。研发人员将继续努力解决这些问题，并提高Ceph的性能和稳定性。</p>',13)])])}const d=t(s,[["render",i]]);export{c as __pageData,d as default};
